        output: stdout,
        executionTime,
        stderr: stderr || null
      });
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 코드 공유
 * POST /api/share
 * Body: { code: string, title: string, description: string }
 */
app.post('/api/share', (req, res) => {
  try {
    const { code, title = 'Untitled', description = '', tags = [] } = req.body;

    if (!code) {
      return res.status(400).json({
        success: false,
        error: 'Code is required'
      });
    }

    // 고유 ID 생성
    const shareId = crypto.randomBytes(8).toString('hex');
    const timestamp = new Date().toISOString();

    const shareData = {
      id: shareId,
      code,
      title,
      description,
      tags,
      createdAt: timestamp,
      updatedAt: timestamp,
      views: 0,
      url: `${req.protocol}://${req.get('host')}/playground?share=${shareId}`
    };

    // 공유 코드 저장
    fs.writeFileSync(
      path.join(SHARE_DIR, `${shareId}.json`),
      JSON.stringify(shareData, null, 2)
    );

    res.json({
      success: true,
      shareId,
      url: shareData.url
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 공유 코드 조회
 * GET /api/share/:shareId
 */
app.get('/api/share/:shareId', (req, res) => {
  try {
    const { shareId } = req.params;
    const filepath = path.join(SHARE_DIR, `${shareId}.json`);

    if (!fs.existsSync(filepath)) {
      return res.status(404).json({
        success: false,
        error: 'Share not found'
      });
    }

    const shareData = JSON.parse(fs.readFileSync(filepath, 'utf8'));

    // 조회수 증가
    shareData.views = (shareData.views || 0) + 1;
    shareData.updatedAt = new Date().toISOString();
    fs.writeFileSync(filepath, JSON.stringify(shareData, null, 2));

    res.json({
      success: true,
      data: shareData
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 모든 공유 코드 목록
 * GET /api/shares?page=1&limit=10&sort=views
 */
app.get('/api/shares', (req, res) => {
  try {
    const { page = 1, limit = 10, sort = 'views' } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    // 공유 폴더의 모든 파일 읽기
    const files = fs.readdirSync(SHARE_DIR).filter(f => f.endsWith('.json'));

    const shares = files.map(file => {
      const data = JSON.parse(fs.readFileSync(path.join(SHARE_DIR, file), 'utf8'));
      return data;
    });

    // 정렬
    if (sort === 'views') {
      shares.sort((a, b) => (b.views || 0) - (a.views || 0));
    } else if (sort === 'latest') {
      shares.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    }

    // 페이지네이션
    const paginated = shares.slice(offset, offset + parseInt(limit));

    res.json({
      success: true,
      data: paginated,
      total: shares.length,
      page: parseInt(page),
      limit: parseInt(limit)
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

