/**
 * FreeLang V4 컴파일러 래퍼
 *
 * Playground 백엔드에서 FreeLang 코드를 실제로 실행하기 위한 모듈
 * 파이프라인: Lexer → Parser → TypeChecker → Compiler → VM
 */

const path = require('path');

// FreeLang V4 컴파일러 모듈 (dist/ 폴더의 빌드 결과물)
let Lexer, Parser, TypeChecker, Compiler, VM;
let compilerLoaded = false;

/**
 * 컴파일러 모듈 로드 (lazy loading)
 */
function loadCompiler() {
  if (compilerLoaded) return true;

  try {
    const v4Path = path.resolve(__dirname, '../../freelang-v4/dist');
    Lexer = require(path.join(v4Path, 'lexer')).Lexer;
    Parser = require(path.join(v4Path, 'parser')).Parser;
    TypeChecker = require(path.join(v4Path, 'checker')).TypeChecker;
    Compiler = require(path.join(v4Path, 'compiler')).Compiler;
    VM = require(path.join(v4Path, 'vm')).VM;
    compilerLoaded = true;
    return true;
  } catch (error) {
    console.error('Failed to load FreeLang V4 compiler:', error.message);
    return false;
  }
}

/**
 * FreeLang 코드 실행
 * @param {string} code - FreeLang 소스 코드
 * @param {object} options - 옵션
 *   - noCheck: boolean (타입 체크 건너뛰기, 기본값: false)
 * @returns {object} { success, output, errors, mode }
 */
function runFreeLang(code, options = {}) {
  const startTime = Date.now();

  if (!code || typeof code !== 'string') {
    return {
      success: false,
      errors: ['Code is required and must be a string'],
      output: '',
      executionTime: 0,
      mode: 'none'
    };
  }

  // 컴파일러 로드 시도
  if (!loadCompiler()) {
    return {
      success: false,
      errors: ['FreeLang V4 compiler not available'],
      output: '',
      executionTime: Date.now() - startTime,
      mode: 'compiler-error'
    };
  }

  try {
    // 1. Lexer: 소스 코드 → 토큰
    const lexer = new Lexer(code);
    const { tokens, errors: lexErrors } = lexer.tokenize();

    if (lexErrors && lexErrors.length > 0) {
      return {
        success: false,
        errors: lexErrors.map(e => `Lex error at line ${e.line}: ${e.message}`),
        output: '',
        executionTime: Date.now() - startTime,
        mode: 'real',
        stage: 'lexer'
      };
    }

    // 2. Parser: 토큰 → AST
    const parser = new Parser(tokens);
    const { program, errors: parseErrors } = parser.parse();

    if (parseErrors && parseErrors.length > 0) {
      return {
        success: false,
        errors: parseErrors.map(e => `Parse error at line ${e.line}: ${e.message}`),
        output: '',
        executionTime: Date.now() - startTime,
        mode: 'real',
        stage: 'parser'
      };
    }

    // 3. TypeChecker: AST 타입 검사 (옵션)
    if (!options.noCheck) {
      const checker = new TypeChecker();
      const typeErrors = checker.check(program);

      if (typeErrors && typeErrors.length > 0) {
        return {
          success: false,
          errors: typeErrors.map(e => `Type error at line ${e.line}: ${e.message}`),
          output: '',
          executionTime: Date.now() - startTime,
          mode: 'real',
          stage: 'type-check'
        };
      }
    }

    // 4. Compiler: AST → 바이트코드
    const compiler = new Compiler();
    let chunk;

    try {
      chunk = compiler.compile(program);
    } catch (compileError) {
      return {
        success: false,
        errors: [`Compilation error: ${compileError.message}`],
        output: '',
        executionTime: Date.now() - startTime,
        mode: 'real',
        stage: 'compiler'
      };
    }

    // 5. VM: 바이트코드 실행
    const vm = new VM();
    const { output, error: vmError } = vm.run(chunk);

    if (vmError) {
      return {
        success: false,
        errors: [`Runtime error: ${vmError}`],
        output: output.join('\n'),
        executionTime: Date.now() - startTime,
        mode: 'real',
        stage: 'vm'
      };
    }

    // 성공
    return {
      success: true,
      output: output.join('\n'),
      errors: [],
      executionTime: Date.now() - startTime,
      mode: 'real'
    };

  } catch (error) {
    // 예상치 못한 에러
    return {
      success: false,
      errors: [`Unexpected error: ${error.message}`],
      output: '',
      executionTime: Date.now() - startTime,
      mode: 'real',
      stage: 'unknown'
    };
  }
}

/**
 * 단순 버전: 에러 배열 대신 단일 에러 문자열 반환
 */
function runFreeLangSimple(code, options = {}) {
  const result = runFreeLang(code, options);

  if (result.success) {
    return {
      success: true,
      output: result.output,
      executionTime: result.executionTime,
      mode: result.mode
    };
  } else {
    return {
      success: false,
      error: result.errors.join('\n'),
      output: result.output,
      executionTime: result.executionTime,
      mode: result.mode
    };
  }
}

module.exports = {
  runFreeLang,
  runFreeLangSimple,
  loadCompiler
};

