      return res.status(400).json({
        success: false,
        error: 'Code is required'
      });
    }

    // 임시 파일 생성
    const filename = `code_${Date.now()}.fl`;
    const filepath = path.join(CODE_DIR, filename);

    fs.writeFileSync(filepath, code);

    // 컴파일 실행 (freelang 컴파일러)
    exec(`freelang compile ${filepath}`, (error, stdout, stderr) => {
      fs.unlinkSync(filepath);

      if (error) {
        return res.json({
          success: false,
          error: stderr || error.message,
          stdout
        });
      }

      res.json({
        success: true,
        output: stdout,
        compilationTime: new Date().toISOString()
      });
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

