    const shareData = JSON.parse(fs.readFileSync(filepath, 'utf8'));

    if (title) shareData.title = title;
    if (description) shareData.description = description;
    if (tags) shareData.tags = tags;
    shareData.updatedAt = new Date().toISOString();

    fs.writeFileSync(filepath, JSON.stringify(shareData, null, 2));

    res.json({
      success: true,
      data: shareData
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: error.message
    });
  }
});

/**
 * 공유 코드 삭제
 * DELETE /api/share/:shareId
