  let n = len(arr)
  let mut i = 0
  while i < n {
    let mut j = 0
    while j < n - i - 1 {
      if arr[j] > arr[j + 1] {
        let temp = arr[j]
        arr[j] = arr[j + 1]
        arr[j + 1] = temp
      }
      j = j + 1
    }
