 */
app.post('/api/run', (req, res) => {
  try {
    const { code, timeout = 5000 } = req.body;

    if (!code) {
      return res.status(400).json({
        success: false,
        error: 'Code is required'
      });
    }

    // FreeLang V4 컴파일러 직접 사용 (컴파일 → 실행)
    const result = runFreeLangSimple(code, { noCheck: false });

    // 컴파일러 로드 실패 시 Mock 모드로 폴백
    if (result.mode === 'compiler-error') {
      const mockOutput = mockExecuteCode(code);
      return res.json({
        success: true,
        output: mockOutput,
        executionTime: 10,
        mode: 'mock',
        message: 'Using mock execution (FreeLang V4 compiler not available)'
      });
    }

    res.json({
      success: result.success,
      output: result.output || result.error || '',
      error: result.error || null,
      executionTime: result.executionTime,
      mode: result.mode,
      stderr: result.error ? result.error : null
    });
  } catch (error) {
    // 예상치 못한 에러: Mock 모드로 폴백
    const { code } = req.body;
    const mockOutput = mockExecuteCode(code || '');
    res.json({
      success: true,
      output: mockOutput,
      executionTime: 0,
      mode: 'mock-error',
      error: error.message,
      message: 'Exception occurred, using mock execution'
    });
  }
});

